        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var T = function(k) { return self._t(k); };
            var hs = history.map(function(r) { return r.results && typeof r.results.healthScore === 'number' ? r.results.healthScore : 0; });
            var avgHealth = Math.round(hs.reduce(function(s, v) { return s + v; }, 0) / hs.length);
            var finalHealth = Math.max(0, Math.min(100, Math.round(hs[hs.length - 1] || 0)));
            var last = history[history.length - 1].results || {};
            var dec = history.map(function(r) { return r.decisions || {}; });
            var tier = this._band(finalHealth);
            var tierId = tier.toLowerCase().replace(/ /g, '_');
            var n = dec.length;
            var count = function(fn) { var c = 0; for (var i = 0; i < n; i++) { if (fn(dec[i], i)) c++; } return c; };
            var avg = function(k, a, b) { var t = 0, c = 0; for (var i = a; i < Math.min(b, n); i++) { t += Number(dec[i][k]) || 0; c++; } return c ? t / c : 0; };

            // Mistakes, detected from the decisions actually submitted (never described unless made)
            var mistakes = [];
            if (avg('hygieneThreshold', 0, 4) >= 120) mistakes.push('m_hygiene');
            if (count(function(d) { return d.variablePay >= 50; }) >= Math.ceil(n / 2)) mistakes.push('m_highvar');
            var earlyVp = avg('variablePay', 0, 4);
            if (n >= 5 && count(function(d, i) { return i >= 4 && d.variablePay <= 25 && d.accelerator <= 1.2; }) >= 2 && earlyVp >= 28) mistakes.push('m_costchase');
            if (count(function(d) { return d.rebalanceEffort >= 70; }) >= 3) mistakes.push('m_rebalance');
            if (count(function(d) { return d.accelerator > 2.2; }) >= Math.ceil(n / 2)) mistakes.push('m_accel');
            if (count(function(d) { return d.accelerator > 2.0 && d.hygieneThreshold >= 75; }) >= 1) mistakes.push('m_pullforward');
            var changes = 0;
            for (var i = 1; i < n; i++) {
                if (Math.abs((dec[i].variablePay || 0) - (dec[i - 1].variablePay || 0)) / 50 + Math.abs((dec[i].accelerator || 0) - (dec[i - 1].accelerator || 0)) / 2 >= 0.15) changes++;
            }
            if (changes >= 4) mistakes.push('m_churn');
            if (typeof last.territoryVariance === 'number' && last.territoryVariance > 25) mistakes.push('m_drift');

            // Turning point: the quarter with the largest fall in health, else the largest rise
            var tpIdx = -1, tpDelta = 0;
            for (var j = 1; j < n; j++) { var dlt = hs[j] - hs[j - 1]; if (dlt <= -3 && dlt < tpDelta) { tpDelta = dlt; tpIdx = j; } }
            var tpKind = 'fall';
            if (tpIdx < 0) { tpKind = 'rise'; tpDelta = 1; for (var k2 = 1; k2 < n; k2++) { var d2 = hs[k2] - hs[k2 - 1]; if (d2 > tpDelta) { tpDelta = d2; tpIdx = k2; } } }
            var turning = null;
            if (tpIdx > 0) {
                var td = dec[tpIdx];
                turning = this._fmt(T(tpKind === 'fall' ? 'cm_tp_fall' : 'cm_tp_rise'), {
                    q: tpIdx + 1, pts: Math.abs(tpDelta), reb: td.rebalanceEffort, vp: td.variablePay,
                    acc: Number(td.accelerator).toFixed(1), hyg: td.hygieneThreshold
                });
            }

            var insights = mistakes.map(function(m) { return self._fmt(T('cm_' + m), { n: changes }); });
            if (!mistakes.length) insights.push(T('cm_clean'));
            if (typeof last.pipelineCoverage === 'number') {
                insights.push(this._fmt(T(last.pipelineCoverage >= 3.5 && last.pipelineCoverage <= 4.5 ? 'cm_band_in' : 'cm_band_out'), { cov: this._num(last.pipelineCoverage, 1) }));
            }
            insights.push(this._fmt(T('cm_unscored'), { cos: this._num(last.costOfSales, 1), att: last.attritionRate }));

            return {
                finalHealthScore: finalHealth,
                averageHealthScore: avgHealth,
                finalARR: last.arr || 0,
                finalQuotaAttainment: last.quotaAttainment || 0,
                territoryScore: last.territoryScore, compScore: last.compScore, pipelineScore: last.pipelineScore,
                overallScore: finalHealth, score: finalHealth, totalScore: finalHealth, composite: finalHealth,
                performance: tierId,
                performanceKey: 'tier_' + tierId,
                performanceLabel: T('tier_' + tierId),
                mistakes: mistakes,
                planChanges: changes,
                turningPoint: turning,
                insights: insights,
                totalPeriods: n
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var T = function(k) { return self._t(k); };
            var li = function(arr) { return arr.map(function(x) { return '<li>' + x + '</li>'; }).join(''); };
            var kpi = function(label, val) { return '<div class="salesopt-cm-kpi"><span class="salesopt-cm-kpi-l">' + label + '</span><span class="salesopt-cm-kpi-v">' + val + '</span></div>'; };
            var html = '<div class="salesopt-cm" role="region" aria-label="' + T('cm_title') + '">';
            html += '<h3 class="salesopt-cm-h">' + T('cm_title') + '</h3>';
            html += '<p class="salesopt-cm-score"><strong>' + (summary.overallScore || 0) + '/100</strong> · <span class="salesopt-cm-tier">' + (summary.performanceLabel || '') + '</span></p>';
            html += '<div class="salesopt-cm-kpis">'
                + kpi(T('cm_k_territory'), summary.territoryScore)
                + kpi(T('cm_k_comp'), summary.compScore)
                + kpi(T('cm_k_pipeline'), summary.pipelineScore)
                + kpi(T('cm_k_avg'), summary.averageHealthScore)
                + kpi(T('cm_k_changes'), summary.planChanges)
                + '</div>';
            if (summary.turningPoint) { html += '<h4 class="salesopt-cm-h4">' + T('cm_tp_h') + '</h4><p>' + summary.turningPoint + '</p>'; }
            html += '<h4 class="salesopt-cm-h4">' + T('cm_ins_h') + '</h4><ul>' + li(summary.insights || []) + '</ul>';
            html += '<h4 class="salesopt-cm-h4">' + T('cm_q_h') + '</h4><ol>' + li([T('cm_q1'), T('cm_q2'), T('cm_q3')]) + '</ol>';
            html += '</div>';
            return html;
        }

        _t(key) {
            try { return window.mySimulation.t(key); } catch (e) { return key; }
        }

        _tf(key, fallback) {
            var v = this._t(key);
            return (!v || v === key) ? fallback : v;
        }

        _fmt(str, vars) {
            return String(str).replace(/\{(\w+)\}/g, function(m, k) { return vars[k] !== undefined ? vars[k] : m; });
        }

        _num(v, dp) {
            var lang = (window.vcI18n && window.vcI18n._lang) || 'en';
            var s = Number(v || 0).toFixed(dp);
            return lang === 'es' ? s.replace('.', ',') : s;
        }

        _band(score) {
            if (score >= 82) return 'Excellent';
            if (score >= 68) return 'Good';
            if (score >= 52) return 'Developing';
            return 'Needs Improvement';
        }

        getHint(state, results) {
            if (state.domainState.territoryVariance > 30) return window.mySimulation.t('hint_high_variance');
            if (state.domainState.pipelineCoverage > 5.5) return window.mySimulation.t('hint_bloated_pipeline');
            if (state.domainState.teamMorale < 45) return window.mySimulation.t('hint_low_morale');
            if (state.domainState.attritionRate > 22) return window.mySimulation.t('hint_high_attrition');
            if (results && results.healthScore >= 70) return window.mySimulation.t('hint_good_progress');
            return null;
        }

